ability')) ?></summary><div class="form-grid"><label><?= e(t('Timezone')) ?><select name="timezone"><?php foreach(DateTimeZone::listIdentifiers() as $zone): ?><option value="<?= e($zone) ?>" <?= ($config['timezone'] ?? 'Asia/Colombo')===$zone?'selected':'' ?>><?= e($zone) ?></option><?php endforeach; ?></select></label><label><?= e(t('Activity event (optional)')) ?><select name="event"><?php foreach([''=>'Use the schedule','task_completed'=>'Task completed','focus_completed'=>'Focus completed','habit_checked'=>'Habit checked'] as $event=>$label): ?><option value="<?= e($event) ?>" <?= ($config['event'] ?? '')===$event?'selected':'' ?>><?= e(t($label)) ?></option><?php endforeach; ?></select></label><label><?= e(t('Catch up missed days (0 disables)')) ?><input type="number" name="catch_up_days" min="0" max="30" value="<?= e($config['catch_up_days'] ?? 0) ?>"></label><label><?= e(t('Retries after a failed run')) ?><input type="number" name="retry_limit" min="0" max="3" value="<?= e($config['retry_limit'] ?? 0) ?>"></label><label><?= e(t('Minutes before retry')) ?><input type="number" name="retry_minutes" min="1" max="1440" value="<?= e($config['retry_minutes'] ?? 5) ?>"></label></div><p class="footnote"><?= e(t('Activity events use custom reminders and future activities only. Catch-up is limited to days since the routine was created. Identical actions for the same period run once across routines.')) ?></p></details><label class="checkbox-label"><input type="checkbox" name="enabled" value="1" <?= !empty($editing['enabled']) ? 'checked' : '' ?>><span><?= e(t('Turn on this routine')) ?></span></label><div class="hero-actions"><button><?= e(t('Save routine')) ?></button><?php if ($editing): ?><a href="/automation" class="btn secondary"><?= e(t('Cancel edit')) ?></a><?php endif; ?></div></form></details>
